t6_gpio_pp50:
/* PC13 — 通用推挽输出 50MHz */
RCC->APB2ENR |= RCC_APB2ENR_IOPCEN;
__DSB();
GPIOC->CRH &= ~(0xFUL << 20);
GPIOC->CRH |=  (0x3UL << 20);

t6_adc_ch1:
/* ========================================================================
 * ADC1 CH1 — PA1 (single conversion, 12-bit)
 * ======================================================================== */

/* 1. 时钟使能 */
RCC->APB2ENR |= RCC_APB2ENR_ADC1EN | RCC_APB2ENR_IOPAEN;
__DSB();

/* 1b. ADC 时钟分频 — ADCPRE=/6 (12MHz @ PCLK2=72MHz, ≤14MHz 上限) */
RCC->CFGR &= ~(3UL << 14);         // 清 ADCPRE[1:0]
RCC->CFGR |=  (2UL << 14);         // ADCPRE=10b → PCLK2/6

/* 2. GPIO — PA1 模拟输入 */
GPIOA->CRL &= ~(0xFUL << 4);
// CNF=00 MODE=00 → 模拟输入

/* 3. ADC 配置 (单次转换, 软件触发) */
// 采样时间: 55.5 cycles (推荐用于 12-bit 精度)
ADC1->SMPR2 |= (5UL << 3);  // CH1: 55.5 cycles
ADC1->SQR3 = 1;                 // 转换序列: 1 个通道 = CH1
ADC1->CR2 = 1;                    // ADON 上电

/* 4. 单次转换 */
static uint16_t adc_read_ch1(void) {
    ADC1->CR2 |= (1UL << 22);    // SWSTART
    while (!(ADC1->SR & 2));    // 等待 EOC
    return ADC1->DR & 0xFFF;     // 12-bit result
}

/* 5. 电压换算 (Vref=3.3V) */
static uint32_t adc_to_mv(uint16_t val) {
    return (uint32_t)val * 3300 / 4096;
}

t6_i2c1_std:
/* ========================================================================
 * I2C1 — 100kHz standard mode, SCL=PB6 SDA=PB7
 * CCR=0x0B4 (180), TRISE=0x25 (37)
 * WARNING: STM32F103 I2C has known errata. Consider software I2C for
 *          production use. See f103_known_issues.json.
 * ======================================================================== */

/* 1. Clock enable */
RCC->APB1ENR |= RCC_APB1ENR_I2C1EN;
RCC->APB2ENR |= RCC_APB2ENR_IOPBEN | RCC_APB2ENR_IOPBEN;
__DSB();

/* 2. GPIO — SCL=PB6 AF-OD, SDA=PB7 AF-OD */
GPIOB->CRL &= ~(0xFUL << 24);
GPIOB->CRL |=  (0xFUL << 24);
GPIOB->CRL &= ~(0xFUL << 28);
GPIOB->CRL |=  (0xFUL << 28);

/* 3. I2C1 config */
I2C1->CR2 = 36;               // FREQ = PCLK1 MHz
I2C1->CCR = 0x0B4;       // 100kHz, CCR=180
I2C1->TRISE = 37;                // max rise time = 37
I2C1->CR1 = 1;                  // PE=1, enable

/* 4. Poll write helper — returns 0 = OK, negative = timeout code
 *   (self-contained: no external error-chain dependency) */
#include <stdint.h>
static int i2c1_write(uint8_t dev_addr, uint8_t reg, uint8_t data) {
    uint32_t timeout = 100000;
    while (I2C1->SR2 & (1<<1)) {        // wait BUSY=0
        if (--timeout == 0) return -1;   // I2C BUSY timeout
    }
    I2C1->CR1 |= (1<<8);                 // START
    timeout = 100000;
    while (!(I2C1->SR1 & 1)) {           // wait SB
        if (--timeout == 0) return -2;   // I2C START timeout
    }
    I2C1->DR = (dev_addr << 1);          // ADDR + W
    timeout = 100000;
    while (!(I2C1->SR1 & (1<<1))) {       // wait ADDR
        if (--timeout == 0) return -3;   // I2C ADDR timeout
    }
    (void)I2C1->SR2;                       // clear ADDR
    I2C1->DR = reg;                       // send register
    timeout = 100000;
    while (!(I2C1->SR1 & (1<<7))) {       // wait TXE
        if (--timeout == 0) return -4;   // I2C TXE timeout
    }
    I2C1->DR = data;                      // send data
    timeout = 100000;
    while (!(I2C1->SR1 & (1<<7))) {
        if (--timeout == 0) return -4;   // I2C TXE timeout
    }
    timeout = 100000;
    while (!(I2C1->SR1 & (1<<2))) {       // wait BTF
        if (--timeout == 0) return -5;   // I2C BTF timeout
    }
    I2C1->CR1 |= (1<<9);                  // STOP
    return 0;
}

t6_systick_1k:
/* SysTick — 1000Hz (1000us interval), 72MHz core clock */
SysTick->LOAD = 71999;         // 72MHz/1000 - 1
SysTick->VAL  = 0;
SysTick->CTRL = SysTick_CTRL_ENABLE | SysTick_CTRL_TICKINT | SysTick_CTRL_CLKSOURCE;

/* 基于 SysTick 的延时计数 */
static volatile uint32_t tick_ms;

/* SysTick ISR */
void SysTick_Handler(void) {
    tick_ms++;                  // F-087: 必须递增, 否则 delay_ms 永久挂死
    // called every 1000us — 用户代码加在这里
}

void delay_ms(uint32_t ms) {
    uint32_t start = tick_ms;
    while ((tick_ms - start) < ms) { __WFI(); }
}
